CREATE MEMORY TABLE "PUBLIC"."EMPLOYEE_MAIN"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 69) NOT NULL,
    "CREATED_DATE" TIMESTAMP(6),
    "DATE_OF_JOIN" DATE,
    "DEPARTMENT" CHARACTER VARYING(255) NOT NULL,
    "EMAIL" CHARACTER VARYING(100) NOT NULL,
    "NAME" CHARACTER VARYING(255),
    "ROLE" CHARACTER VARYING(255),
    "SALARY" NUMERIC(10, 2),
    "STATUS" ENUM('ACTIVE', 'INACTIVE', 'TERMINATED'),
    "UPDATED_DATE" TIMESTAMP(6),
    "VERSION" BIGINT
);
ALTER TABLE "PUBLIC"."EMPLOYEE_MAIN" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4" PRIMARY KEY("ID");
